INSERT INTO `briefs` (`id`, `title`, `description`, `category_id`, `budget`, `deadline`, `publish_date`) VALUES
(1, 'Modern Website Redesign for Local Restaurant', 'We are looking for a creative freelancer or agency to redesign our restaurant\'s website. The new design should be modern, mobile-friendly, and easy to navigate. The project should include a responsive homepage, menu page, online reservation form, and contact section. Experience with UX/UI design and SEO-friendly layouts is preferred.', 1, 4500.0000, '2027-09-15', '2027-01-01'),
(2, 'Monthly Social Media Content Creation', 'Seeking a content creator to produce engaging content for our social media platforms for one month. Deliverables include 12 Instagram posts, 8 Facebook posts, 4 LinkedIn posts, and accompanying captions. The content should align with our brand identity and include basic graphic design where necessary.', 2, 1800.0000, '2027-08-20', '2027-07-25'),
(3, 'Corporate Promotional Video Production', 'We need a professional videographer to create a 2–3 minute promotional video showcasing our company\'s services and team. The project includes pre-production planning, one full day of filming, drone footage (if available), professional editing, colour grading, background music, and delivery in Full HD and 4K formats.', 3, 6500.0000, '2027-10-01', '2027-07-25');